cat > /tmp/fuzz2.pl <<'EOF'
my $B="/workspace/dataset/test5_executable";
sub lc_ascii { my $s=shift; $s=~tr/A-Z/a-z/; return $s; }
sub conv {
  my ($s)=@_; my @c=split //,$s; my $i=0;
  $i++ while $i<@c && $c[$i]=~/^[\t\n\x0b\x0c\r ]$/;
  my $neg=0;
  if($i<@c && ($c[$i] eq '+' || $c[$i] eq '-')){ $neg=($c[$i] eq '-'); $i++; }
  return -1 unless $i<@c && $c[$i]=~/^[0-9]$/;
  my $d=""; while($i<@c && $c[$i]=~/^[0-9]$/){ $d.=$c[$i]; $i++; }
  $d=~s/^0+(?=.)//;
  return -1 if length($d)>5;
  my $m=0+$d;
  return 0 if $neg && $m==0;
  return -1 if $neg;
  return -1 if $m>65535;
  return $m;
}
sub spec {
  my ($u)=@_;
  my ($sc,$ho,$po,$pa,$qu)=("","",-1,"","");
  my $rest=$u;
  my $hp=index($rest,"#"); $rest=substr($rest,0,$hp) if $hp>=0;
  my $qp=index($rest,"?"); if($qp>=0){ $qu=substr($rest,$qp+1); $rest=substr($rest,0,$qp); }
  my $sp=index($rest,"://");
  if($sp<0){ return ("","",-1,$rest,$qu); }
  $sc=lc_ascii(substr($rest,0,$sp)); $rest=substr($rest,$sp+3);
  my $sl=index($rest,"/"); my $auth;
  if($sl>=0){ $auth=substr($rest,0,$sl); $pa=substr($rest,$sl); } else { $auth=$rest; $pa=""; }
  my $at=index($auth,"\@"); $auth=substr($auth,$at+1) if $at>=0;
  my $co=index($auth,":");
  if($co<0){ return ($sc,$auth,-1,$pa,$qu); }
  $ho=substr($auth,0,$co); $po=conv(substr($auth,$co+1));
  return ($sc,$ho,$po,$pa,$qu);
}
sub run { my($arg)=@_; my $pid=open(my $fh,"-|"); if($pid==0){exec($B,$arg);exit 1;} local $/; my $o=<$fh>; close $fh; return defined($o)?$o:""; }
my @alpha=('0','1','5','6','8','9','+','-',' ',"\t","\n",':','@','/','#','?','.','x','A','%');
srand(9911);
my $bad=0; my $tot=0;
my @cases;
for (1..2000){ my $n=1+int(rand(10)); my $s=""; $s.=$alpha[int(rand(@alpha))] for(1..$n);
  my $pre = (rand()<0.8) ? "http://" : ((rand()<0.5)?"://":"HtTp://");
  push @cases, $pre.$s; }
push @cases, ('http://h/x:80','http://h:0080080','http://h:00065535','http://h:0000065536','http://h:65535:0','http://h:0:65535','http://@:80','http://:@80','http://:80@','http://:80@h:90');
for my $u (@cases){
  $tot++;
  my @e=spec($u); my $exp=join("\n",@e)."\n";
  my $got=run($u);
  if($got ne $exp){
    my $du=$u; $du=~s/([^\x20-\x7e])/sprintf("\\x%02X",ord($1))/ge;
    my $dg=$got; $dg=~s/\n/|/g; my $de=$exp; $de=~s/\n/|/g;
    $dg=~s/([^\x20-\x7e|])/sprintf("\\x%02X",ord($1))/ge; $de=~s/([^\x20-\x7e|])/sprintf("\\x%02X",ord($1))/ge;
    print "DIVERGE url=[$du]\n  spec=[$de]\n  real=[$dg]\n"; $bad++;
    last if $bad>25;
  }
}
print "checked=$tot divergences=$bad\n";
EOF
